import type { Chapter, Topic } from "@/lib/study/schema";

/**
 * Computer Organisation → Main memory and secondary storage (Hamacher, Patterson and Hennessy, Stallings; GATE CS syllabus: "Memory hierarchy: main memory, secondary storage").
 * Numbers from lib/study/memory-hw.ts, checked by scripts/memory-hw-check.ts:
 * 64K × 16 from 16K × 8 chips: 16 address bits, 14 chip address bits, 2 select bits, 4 rows × 2 columns = 8 chips; 1M × 32 from 256K × 1: 128 chips; address 0xC123 → row 3, offset 0x0123.
 * 8 consecutive words, bank access 40 ns, bus 10 ns: one bank 320 ns; 2 banks 170 ns; 4 banks 110 ns (= 40 + 7 × 10); 8 banks 110 ns. Refresh: 8192 rows × 50 ns every 64 ms = 0.64%.
 * Disk 7200 rpm: rotation 8.33 ms, average latency 4.17 ms; seek 6 ms, 200 sectors of 512 B per track: a sector reads in 10.41 ms with 0.2 ms controller, 4 KB in 10.70 ms; streaming 12,288,000 B/s.
 * 16 surfaces × 2000 tracks × 400 sectors × 512 B = 6,553,600,000 B. RAID with 8 disks of 2 TB: RAID 0 16 TB, RAID 1 and 10 8 TB, RAID 5 14 TB, RAID 6 12 TB.
 * Hamming check bits for 4, 8, 16, 32, 64 data bits: 3, 4, 5, 6, 7; SECDED for 64 data bits: 8. Hamming(7,4) of 1011 = 0110011; flip position 5 → syndrome 5.
 */
const TP = "/topics/computer-organization-and-architecture-coa";
const HREF = "/study/main-memory";

/* ------------------------------------------------------------------ 1. Chips and decoding */
const chipT: Topic = {
  id: "cs.coa.memchips",
  title: "Main memory: SRAM, DRAM, chip arrays and address decoding",
  blocks: [
    { type: "hook", text: "Behind the cache sits main memory, built from thousands of identical chips. The processor sends one address and gets one word back, yet that word is spread over several chips, each of which holds only a slice of the address space and a slice of the word width. Understanding how the address is split between a decoder and the chips themselves is the key to every memory-design question." },
    { type: "objectives", items: ["Compare SRAM, DRAM, ROM and flash memory cells and say where each is used.", "Compute the capacity and the number of address and data lines of a memory chip.", "Design a large memory from smaller chips: chips needed, decoder size, address ranges.", "Explain the multiplexed row and column addressing of a DRAM."] },
    { type: "intuition", paras: ["A memory chip is a table. It has A address pins, so it has 2ᴬ rows, and each row is W bits wide, so its capacity is 2ᴬ × W bits. The processor puts an address on the lines, raises a chip-select signal and a read or write signal, and one row of W bits appears on or is taken from the data pins.", "Real memories are larger and wider than any one chip, so we tile chips like bricks. Placing chips side by side makes the word wider: two 8-bit chips make a 16-bit word. Stacking chips makes the memory deeper: four chips of 16K words make 64K words. Each stack needs its own chip-select, and a decoder generates it from the top address bits, while the low address bits go to every chip in parallel.", "Two cell designs dominate. A static RAM cell is a latch of about six transistors: it keeps its value as long as power is on, is very fast, and takes a lot of area, so it is used for caches. A dynamic RAM cell is one transistor and one capacitor: very small and cheap, so main memory is DRAM, but the charge leaks away and every row must be rewritten (refreshed) every few milliseconds."] },
    { type: "definition", name: "Memory chip and array arithmetic", text: "For a memory of M words of W bits built from chips of m words of w bits:", items: ["Capacity of a chip = 2ᴬ × w bits (A address pins). Address lines for the memory = log₂ M.", "Chips per row = W / w (to make the word wide). Rows of chips = M / m (to make it deep). Total chips = (M / m) × (W / w).", "Chip address lines = log₂ m, connected to the low bits of the address. The remaining log₂ (M / m) high bits go to a decoder with that many inputs and M / m outputs, one chip-select per row.", "SRAM: ~6 transistors per bit, fast, no refresh, costly (cache). DRAM: 1 transistor + 1 capacitor per bit, slower, needs refresh, cheap (main memory). ROM, PROM, EPROM, EEPROM, flash: non-volatile; flash is read quickly and written in blocks.", "DRAM chips multiplex the address: the row address is sent first (RAS), then the column address (CAS) on the same pins, halving the pin count."] },
    { type: "deep", sections: [
      { h: "A worked design", paras: ["Build a 64K × 16-bit memory from 16K × 8-bit chips. The memory has 64K = 2¹⁶ words, so 16 address bits. A chip has 16K = 2¹⁴ words, so 14 address pins, connected to address bits A₁₃ … A₀. To make a 16-bit word we need 16 / 8 = 2 chips side by side (columns). To reach 64K words we need 64K / 16K = 4 rows. Total 4 × 2 = 8 chips.", "The two high bits A₁₅ A₁₄ drive a 2-to-4 decoder whose four outputs select the four rows. Row 0 holds addresses 0000₁₆ to 3FFF₁₆, row 1 holds 4000₁₆ to 7FFF₁₆, row 2 8000₁₆ to BFFF₁₆, row 3 C000₁₆ to FFFF₁₆. The address C123₁₆ has A₁₅A₁₄ = 11, so it selects row 3, and the low 14 bits 0123₁₆ pick word 291 in each of the two chips of that row.", "Now a 1M × 32 memory from 256K × 1 chips. Rows = 1M / 256K = 4; columns = 32 / 1 = 32; chips = 128. Address lines: 20, of which 18 go to the chips and 2 to a 2-to-4 decoder."] },
      { h: "Byte and word addressing", paras: ["Most machines are byte addressable: each address names a byte, and a 32-bit word occupies four consecutive addresses. A memory built with 32-bit-wide rows is therefore addressed with the two low address bits selecting the byte inside the row (byte enables), and only the upper bits drive the decoder and chip addresses. In a question, check whether 'size' means words or bytes before you count address bits: a 64 KB byte-addressable memory has 16 address bits, but 64 K words of 4 bytes has 16 word-address bits plus 2 byte bits = 18 bits."] },
      { h: "Memory maps", paras: ["A processor's address space is shared out among RAM, ROM and I/O. With a 16-bit address, a 32 KB ROM at the top and a 32 KB RAM at the bottom needs one decoder bit: A₁₅ = 0 selects RAM (0000 – 7FFF) and A₁₅ = 1 selects ROM (8000 – FFFF). If A₁₅ alone is used and the chips are smaller than 32 KB, the remaining bits are decoded further. Using fewer address bits than needed (partial decoding) makes a chip appear at several addresses (aliases)."] },
      { h: "Inside a DRAM", paras: ["A 4M × 1 DRAM holds 2²² bits arranged as a square array of 2048 rows × 2048 columns. The 22-bit address is sent in two halves over 11 pins: the row address first, latched by RAS (row address strobe), then the column address, latched by CAS. The whole row is read into a row buffer and the column selects one bit from it. The read empties the cells, so the row is written back; and every row must be refreshed within the retention time (typically 64 ms) because the capacitors leak.", "Multiplexing saves pins (11 instead of 22), which keeps the package small, at the price of two steps per access. Later DRAMs (page mode, SDRAM, DDR) exploit the row buffer: once a row is open, further accesses to the same row are much faster, as the next topic shows."] },
    ] },
    { type: "walkthrough", steps: ["Compute the address bits of the whole memory: log₂ of its size in words (or bytes).", "Compute the chip's address bits: log₂ of its words.", "Columns = memory word width / chip width; rows = memory words / chip words; chips = rows × columns.", "Decoder inputs = log₂ rows (these are the top address bits); outputs = rows.", "To find where an address goes: divide by the chip size for the row and take the remainder for the word inside the chip."], prompt: { q: "A 1M-word memory is built from 128K-word chips of the same width. How big is the decoder?", a: "Rows = 1M / 128K = 8, so a 3-to-8 decoder fed by the top 3 of the 20 address bits." } },
    { type: "figure", id: "mem-tbl", for: "ex1", caption: "How the 64K × 16 memory is built from 16K × 8 chips.", alt: "Four rows of two chips; row 0 covers 0000 to 3FFF, row 1 4000 to 7FFF, row 2 8000 to BFFF, row 3 C000 to FFFF; the top two address bits drive a 2 to 4 decoder.", fig: { kind: "matrix", title: "Chip rows", cols: ["address range (hex)", "A15 A14", "chips"], rows: [{ label: "Row 0", cells: ["0000 – 3FFF", "00", 2] }, { label: "Row 1", cells: ["4000 – 7FFF", "01", 2] }, { label: "Row 2", cells: ["8000 – BFFF", "10", 2] }, { label: "Row 3", cells: ["C000 – FFFF", "11", 2], hl: true }] } },
    { type: "figure", id: "cell-tbl", for: "ex2", caption: "The two kinds of read/write memory.", alt: "SRAM has six transistors per cell, is fast, needs no refresh and is used for caches. DRAM has one transistor and one capacitor, is slower, needs refresh and is used for main memory.", fig: { kind: "matrix", title: "SRAM against DRAM", cols: ["cell", "speed", "refresh", "used for"], rows: [{ label: "SRAM", cells: ["≈ 6 transistors", "fast", "no", "caches, registers"] }, { label: "DRAM", cells: ["1 transistor + 1 capacitor", "slower", "yes, every ~64 ms", "main memory"], hl: true }] } },
    { type: "example", id: "ex1", level: "gate", title: "Chips for a 64K × 16 memory", given: "A memory of 64K words of 16 bits is built from chips of 16K words of 8 bits.", find: "The address lines, the number of chips, and the decoder; and where address C123 (hex) goes.",
      steps: [{ say: "64K = 2¹⁶ words, so 16 address lines; a chip has 16K = 2¹⁴ words, so 14 chip address lines.", result: "16 and 14" }, { say: "Columns = 16 / 8 = 2; rows = 64K / 16K = 4; chips = 4 × 2.", result: "8 chips" }, { say: "The top 2 address bits (16 − 14) drive a 2-to-4 decoder.", result: "2-to-4 decoder" }, { say: "C123₁₆ = 1100 0001 0010 0011₂: A₁₅A₁₄ = 11, so row 3; the low 14 bits are 0123₁₆.", result: "row 3, word 0123₁₆" }],
      answer: "16 address lines, 8 chips in 4 rows of 2, a 2-to-4 decoder; address C123 goes to row 3, word 0123.", check: "Enter 64, 16, 16, 8 and the address 49443 in the memory design lab." },
    { type: "example", id: "ex2", level: "gate", title: "A bit-sliced memory", given: "A 1M × 32-bit memory is built from 256K × 1-bit chips.", find: "The number of chips and the width of the address going to each chip.",
      steps: [{ say: "Columns = 32 / 1 = 32; rows = 1M / 256K = 4.", result: "32 and 4" }, { say: "Chips = 32 × 4.", result: "128" }, { say: "Chip address = log₂ 256K = 18 bits; the other 2 of 20 bits go to the decoder.", result: "18 bits" }],
      answer: "128 chips; 18 address lines per chip and a 2-to-4 decoder.", check: "Each doubling of the memory depth doubles the number of chips." },
    { type: "example", id: "ex3", level: "edge", title: "A word of 4 bytes", given: "A byte-addressable machine has 32-bit words. Its memory is 1M words built from 256K × 8 chips.", find: "The chips needed and the address bits.",
      steps: [{ say: "1M words × 4 bytes = 4 MB, so 22 byte-address bits (2 of them select the byte in a word).", result: "22 bits" }, { say: "A row of 32-bit width needs 32 / 8 = 4 chips; depth 1M / 256K = 4 rows.", result: "4 × 4" }, { say: "Chips = 16.", result: "16 chips" }],
      answer: "16 chips; 22 byte-address bits, of which 2 pick the byte.", check: "Always check whether the size is given in words or in bytes." },
    { type: "lab", lab: "mem-design" },
    { type: "faded", title: "Your turn", given: "A 32K × 8 memory is to be built from 4K × 4 chips.", steps: [{ say: "Chips per row and number of rows?", blank: true, answer: "2 chips per row (8/4); 8 rows (32K/4K)." }, { say: "Total chips and decoder?", blank: true, answer: "16 chips; a 3-to-8 decoder." }, { say: "Address bits of the memory and of each chip?", blank: true, answer: "15 bits; 12 bits." }] },
    { type: "trap", wrong: "A memory built from chips with the same capacity always needs the same decoder.", tempting: "Capacity decides the number of chips.", whyWrong: "The decoder is set by the number of rows (depth), not by the width. Eight chips can be 8 rows of 1 (3-to-8 decoder) or 4 rows of 2 (2-to-4 decoder).", rule: "Decoder inputs = log₂ (memory words / chip words)." },
    { type: "trap", wrong: "DRAM is faster than SRAM because it is denser.", tempting: "Small cells mean short wires.", whyWrong: "A DRAM cell is a tiny capacitor that must be sensed and rewritten; SRAM is faster and costlier. Density makes DRAM cheap, not fast.", rule: "SRAM for speed (cache), DRAM for size (main memory)." },
    { type: "trap", wrong: "A DRAM needs the full address on its pins at once.", tempting: "Every memory is addressed by the full address.", whyWrong: "DRAMs take the address in two halves (row, then column) on shared pins.", rule: "Multiplexed addressing halves the address pins." },
    { type: "shortcut", text: "Chips = (M / m) × (W / w). Decoder = log₂ (M / m) inputs. Chip address lines = log₂ m. Total address lines = log₂ M. Address → row = address ÷ m, offset = address mod m.", validWhen: "All sizes are powers of two and in the same unit (words or bytes)." },
    { type: "gate", text: "GATE asks for the number of chips and the decoder size to build a memory from smaller chips, the address range selected by a decoder output, the address and data lines of a chip, and the difference between SRAM and DRAM (including multiplexed addressing). Memory-design questions appear regularly." },
    { type: "recall", cards: [{ q: "Chips needed", a: "(M / m) × (W / w)" }, { q: "Decoder", a: "log₂ rows inputs, rows outputs" }, { q: "SRAM cell", a: "≈ 6 transistors, fast, no refresh" }, { q: "DRAM cell", a: "1 transistor + 1 capacitor, refresh" }, { q: "DRAM address", a: "row (RAS) then column (CAS) on shared pins" }] },
    { type: "check", questions: [
      { id: "mc1", kind: "NAT", marks: 1, q: "How many 16K × 8-bit chips are needed to build a 64K × 16-bit memory?", answer: "8", solution: "(64K / 16K) × (16 / 8) = 4 × 2." },
      { id: "mc2", kind: "NAT", marks: 2, q: "A 1M × 32-bit memory is built from 256K × 1-bit chips. How many chips are needed?", answer: "128", solution: "4 rows × 32 columns." },
      { id: "mc3", kind: "NAT", marks: 1, q: "In the 64K × 16 design from 16K × 8 chips, how many inputs does the chip-select decoder have?", answer: "2", solution: "4 rows need a 2-to-4 decoder." },
      { id: "mc4", kind: "NAT", marks: 2, q: "A 32K × 8 memory is built from 4K × 4 chips. How many chips are needed?", answer: "16", solution: "(32K / 4K) × (8 / 4) = 8 × 2." },
      { id: "mc5", kind: "MSQ", marks: 2, q: "Which statements about SRAM and DRAM are true?", options: ["SRAM needs no refresh", "A DRAM cell is one transistor and one capacitor", "DRAM is used for caches because it is faster", "DRAM addresses are usually multiplexed into row and column"], answer: "A, B, D", solution: "Caches use SRAM, which is faster." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Memory chips and decoding", href: TP }, { label: "Topic 2: interleaving and DRAM timing", sub: "Bandwidth", href: HREF }, { label: "Topic 3: disks and RAID", sub: "Access time", href: HREF }] },
    { type: "links", prereq: ["Decoders (DL)", "Powers of two"], usedIn: ["Interleaving", "Cache design", "Virtual memory"], cross: ["DL: decoders and memory chips", "OS: physical memory"] },
  ],
};

/* ------------------------------------------------------------------ 2. Interleaving and DRAM timing */
const ilT: Topic = {
  id: "cs.coa.meminterleave",
  title: "Memory performance: interleaving, burst access and DRAM refresh",
  blocks: [
    { type: "hook", text: "A DRAM bank needs tens of nanoseconds to deliver a word, while the processor and the bus can move words ten times faster. One answer is to keep several banks busy at once, so that while one is still thinking about word 0, another is already working on word 1. Another is to read a whole row once it is open. And always, a little of the time must be spent on refresh." },
    { type: "objectives", items: ["Distinguish access time from cycle time and compute memory bandwidth.", "Compute the time to read consecutive words from an interleaved memory.", "Explain why more banks than needed do not help and why low-order interleaving suits sequential access.", "Compute the time lost to DRAM refresh."] },
    { type: "intuition", paras: ["Access time is the delay between a request and the data arriving. Cycle time is the minimum time between two requests to the same bank; for DRAM it is longer, because the row must be restored. Bandwidth is how much data comes out each second: for a bus W bits wide with a transfer every T seconds it is W / T.", "If one bank is used, reading n words takes n access times. With m banks, consecutive addresses are placed in consecutive banks (low-order interleaving: the bank number is the low bits of the address, address mod m). The processor asks for word 0 from bank 0, a moment later for word 1 from bank 1, and so on. The accesses overlap, and after the first has finished, a word comes out every bus time.", "High-order interleaving does the opposite: the high bits choose the bank, so consecutive words are in the same bank. This is how you build a bigger memory from chips (the previous topic), but it does nothing for speed on sequential accesses."] },
    { type: "definition", name: "Interleaved access", text: "m banks, each taking tA to access, a bus moving one word in tB, words requested every tB:", items: ["One bank: n words take n × tA.", "Enough banks (m ≥ tA / tB): n words take tA + (n − 1) × tB; a word arrives every tB after the first.", "Too few banks (m < tA / tB): a bank is not ready when its next word is requested, and the speed is limited to m words per tA.", "Bank number = address mod m (low-order interleaving).", "DRAM refresh overhead = (rows × time to refresh one row) / refresh interval."] },
    { type: "deep", sections: [
      { h: "A worked example", paras: ["Bank access time 40 ns, bus time 10 ns, 8 consecutive words. One bank: 8 × 40 = 320 ns.", "Four banks: word k is requested at 10k ns and goes to bank k mod 4. Words 0 to 3 start at 0, 10, 20, 30 and finish at 40, 50, 60, 70. Word 4 needs bank 0 again, which is free at 40, so it starts at 40; likewise 5, 6, 7 start at 50, 60, 70, finishing at 80, 90, 100, 110. Total 110 ns = 40 + 7 × 10, a speed-up of 2.9 over the single bank.", "Two banks: only two accesses overlap. Word 2 must wait for bank 0 (free at 40), word 3 for bank 1 (free at 50), and so on: the total is 170 ns. Eight banks: still 110 ns. Four banks were enough, since tA / tB = 4; the extra banks sit idle."] },
      { h: "When interleaving fails", paras: ["Interleaving helps when consecutive addresses are accessed. If a program steps through memory with a stride equal to the number of banks (for example, down a column of a matrix stored row by row, with a power-of-two row length), every access lands in the same bank and the speed falls back to one bank. Some machines use a prime number of banks to avoid this."] },
      { h: "Row buffers and burst access", paras: ["A modern DRAM reads a whole row into a row buffer. The first access to a row costs the full time (open the row, select the column, say 60 ns); later accesses to the same row only need a column selection (say 20 ns). A burst of 8 words from one row therefore takes 60 + 7 × 20 = 200 ns instead of 8 × 60 = 480 ns. This is page mode, and in SDRAM and DDR it is combined with a clock and with transferring on both clock edges (DDR), doubling the bandwidth of the same bus.", "Bandwidth example: a 64-bit bus at 100 MHz moves 8 bytes every 10 ns, 800 MB/s; with double data rate, 1600 MB/s."] },
      { h: "The cost of refresh", paras: ["Each DRAM row must be refreshed within the retention time, 64 ms for most chips. If the chip has 8192 rows and refreshing one takes 50 ns, one pass costs 8192 × 50 ns = 409.6 µs, which is 0.64% of every 64 ms. Refresh can be done in a burst (all rows at once, then a long gap) or distributed (one row every 64 ms / 8192 ≈ 7.8 µs). Distributed refresh avoids one long stall that could break a real-time deadline.", "A memory request that arrives during a refresh waits: this adds a little to the average access time and is part of why measured DRAM latency varies."] },
    ] },
    { type: "walkthrough", steps: ["Find the single-bank time: n × tA.", "For m banks, issue word k at time k × tB to bank k mod m.", "A word starts when both it has been requested and its bank is free; it finishes tA later.", "The total time is the finish time of the last word.", "If m ≥ tA / tB the total is tA + (n − 1) × tB; adding more banks changes nothing."], prompt: { q: "What is the least number of banks that lets a word arrive every tB?", a: "m = tA / tB, rounded up (tA = 40, tB = 10 gives 4)." } },
    { type: "figure", id: "il-tbl", for: "ex1", caption: "8 consecutive words, tA = 40 ns, tB = 10 ns.", alt: "One bank 320 ns, two banks 170 ns, four banks 110 ns, eight banks 110 ns.", fig: { kind: "matrix", title: "Time for 8 words", cols: ["ns", "speed-up"], rows: [{ label: "1 bank", cells: [320, "1.00"] }, { label: "2 banks", cells: [170, "1.88"] }, { label: "4 banks", cells: [110, "2.91"], hl: true }, { label: "8 banks", cells: [110, "2.91"] }] } },
    { type: "figure", id: "burst-tbl", for: "ex2", caption: "A burst of 8 words from one DRAM row (first 60 ns, then 20 ns each).", alt: "Eight separate random accesses take 480 ns; a burst takes 200 ns.", fig: { kind: "matrix", title: "Random against burst", cols: ["ns"], rows: [{ label: "8 random accesses (8 × 60)", cells: [480] }, { label: "Burst: 60 + 7 × 20", cells: [200], hl: true }] } },
    { type: "example", id: "ex1", level: "gate", title: "Time to read from interleaved banks", given: "Banks need 40 ns to access a word; the bus moves a word in 10 ns. 8 consecutive words are read.", find: "The time with 1, 2 and 4 banks.",
      steps: [{ say: "One bank: 8 × 40.", result: "320 ns" }, { say: "Four banks (m = tA / tB): 40 + 7 × 10.", result: "110 ns" }, { say: "Two banks: only two accesses overlap; simulating the bank-free times gives 170 ns.", result: "170 ns" }],
      answer: "320 ns, 170 ns and 110 ns.", check: "Try 8 banks in the interleaving lab: still 110 ns." },
    { type: "example", id: "ex2", level: "gate", title: "A burst against random reads", given: "A DRAM row access takes 60 ns, and each further word in the open row takes 20 ns.", find: "The time to read 8 words from the same row, and from 8 different rows.",
      steps: [{ say: "Same row: 60 + 7 × 20.", result: "200 ns" }, { say: "Different rows: each needs a full access, 8 × 60.", result: "480 ns" }],
      answer: "200 ns against 480 ns.", check: "Locality lets the row buffer pay off." },
    { type: "example", id: "ex3", level: "edge", title: "The overhead of refresh", given: "A DRAM has 8192 rows, refreshing one row takes 50 ns, and every row must be refreshed every 64 ms.", find: "The fraction of time spent refreshing.",
      steps: [{ say: "One pass = 8192 × 50 ns = 409.6 µs.", result: "409.6 µs" }, { say: "Fraction = 409.6 µs / 64 ms.", result: "0.64%" }],
      answer: "0.64% of the time.", check: "Doubling the rows doubles the overhead unless the refresh is done several rows at a time." },
    { type: "lab", lab: "mem-interleave" },
    { type: "faded", title: "Your turn", given: "Bank access time 60 ns, bus time 15 ns, 10 consecutive words.", steps: [{ say: "Time with one bank?", blank: true, answer: "10 × 60 = 600 ns." }, { say: "Least banks for full overlap, and the time with them?", blank: true, answer: "60 / 15 = 4 banks; 60 + 9 × 15 = 195 ns." }, { say: "With 16 banks?", blank: true, answer: "Still 195 ns." }] },
    { type: "trap", wrong: "More banks always give a proportionally shorter time.", tempting: "Parallelism scales.", whyWrong: "Once there are tA / tB banks the bus is the limit; extra banks sit idle (110 ns for 4 or 8 banks).", rule: "Speed-up saturates at about tA / tB." },
    { type: "trap", wrong: "Interleaving speeds up every access pattern.", tempting: "Banks work in parallel.", whyWrong: "It only helps when successive accesses go to different banks. Strided access that hits one bank every time runs at single-bank speed.", rule: "Interleaving helps sequential access." },
    { type: "trap", wrong: "Access time and cycle time are the same thing.", tempting: "Both are delays.", whyWrong: "Access time is request-to-data; cycle time is the minimum gap between requests, and is longer for DRAM because the row is restored.", rule: "Cycle time ≥ access time." },
    { type: "shortcut", text: "Interleaved time = tA + (n − 1) × tB when m ≥ tA / tB; otherwise simulate bank-free times. Burst = first + (n − 1) × next. Refresh overhead = rows × tRow / interval.", validWhen: "Consecutive addresses, low-order interleaving, one word per bus transfer." },
    { type: "gate", text: "GATE asks for the time to read consecutive words from interleaved memory, the number of banks needed, burst-mode access time, memory bandwidth and the percentage of time lost to refresh." },
    { type: "recall", cards: [{ q: "Low-order interleaving", a: "bank = address mod m" }, { q: "Interleaved time", a: "tA + (n − 1) tB (enough banks)" }, { q: "Banks needed", a: "tA / tB" }, { q: "Bus bandwidth", a: "width / transfer time" }, { q: "Refresh overhead", a: "rows × tRow / interval" }] },
    { type: "check", questions: [
      { id: "mi1", kind: "NAT", marks: 1, q: "A bank takes 40 ns per access and the bus takes 10 ns per word. How many ns to read 8 consecutive words from a single bank?", answer: "320", solution: "8 × 40." },
      { id: "mi2", kind: "NAT", marks: 2, q: "With the same timing, how many ns to read 8 consecutive words from a 4-way interleaved memory?", answer: "110", solution: "40 + 7 × 10." },
      { id: "mi3", kind: "NAT", marks: 2, q: "Same timing and words, but 2-way interleaved. How many ns?", answer: "170", solution: "Only two banks overlap; word 2 waits for bank 0 until 40 ns, and so on." },
      { id: "mi4", kind: "NAT", marks: 2, q: "A DRAM has 8192 rows, 50 ns to refresh a row, and a 64 ms refresh interval. What percentage of time is spent refreshing (two decimals)?", answer: "0.64", solution: "8192 × 50 ns / 64 ms." },
      { id: "mi5", kind: "MSQ", marks: 2, q: "Which statements about interleaving are true?", options: ["Low-order interleaving places consecutive words in consecutive banks", "It helps a program that accesses memory sequentially", "Any number of extra banks keeps shortening the time", "A stride equal to the number of banks defeats it"], answer: "A, B, D", solution: "Beyond tA / tB banks the bus is the limit." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Interleaving and DRAM", href: TP }, { label: "Topic 1: chips and decoding", sub: "Memory design", href: HREF }, { label: "Topic 3: disks and RAID", sub: "Access time", href: HREF }] },
    { type: "links", prereq: ["Memory chips and decoding", "Cache miss penalty"], usedIn: ["Cache miss penalty", "Virtual memory performance"], cross: ["OS: effective access time"] },
  ],
};

/* ------------------------------------------------------------------ 3. Disks */
const diskT: Topic = {
  id: "cs.coa.disks",
  title: "Secondary storage: disk access time, capacity, RAID and flash",
  blocks: [
    { type: "hook", text: "Main memory forgets everything when the power goes off, and it is too small to hold all your data. Secondary storage keeps it: spinning disks that are large and cheap but a million times slower than memory, and flash drives that have no moving parts. The time to reach a byte on a disk is dominated by mechanical movement, and the arithmetic of that time is among the most regular questions in the paper." },
    { type: "objectives", items: ["Describe a disk's geometry: platters, surfaces, tracks, cylinders and sectors, and compute capacity.", "Compute average access time from seek, rotational latency, transfer and controller times.", "Compute the capacity, fault tolerance and write cost of RAID levels 0, 1, 5 and 6.", "Explain how flash storage differs from a disk."] },
    { type: "intuition", paras: ["A disk is a stack of platters spinning together. Each platter has two surfaces, each read by its own head, and each surface is divided into concentric tracks, each track into sectors. All the heads move together on one arm assembly, so the tracks at the same position on every surface form a cylinder: reading a whole cylinder needs no further head movement.", "To read a sector the disk must do three things in order. Move the heads to the right track (the seek). Wait for the sector to come round under the head (rotational latency, on average half a turn). Read the sector as it passes (the transfer). A controller adds a small overhead. The first two are mechanical and cost milliseconds; the transfer of one sector is microseconds. This is why reading many sectors in a row is so much cheaper per byte than reading them at random.", "A single disk can fail and is slower than it could be. RAID (a redundant array of independent disks) combines several: some levels stripe data across disks for speed, some mirror it, and some store parity so that the contents of a failed disk can be rebuilt from the rest."] },
    { type: "definition", name: "Disk formulas", text: "For a disk of s surfaces, t tracks per surface, n sectors per track of b bytes, turning at R rpm:", items: ["Capacity = s × t × n × b. Bytes per track = n × b. A cylinder has s tracks.", "Rotation time = 60 / R seconds. Average rotational latency = half of that.", "Transfer time of x bytes = (x / bytes per track) × rotation time. Streaming rate = bytes per track × R / 60.", "Average access time = average seek + average rotational latency + transfer time + controller time.", "RAID 0: striping, capacity N·d, survives 0 failures. RAID 1/10: mirroring, N·d / 2, survives 1. RAID 5: one parity block per stripe spread over the disks, (N − 1)·d, survives 1. RAID 6: two parities, (N − 2)·d, survives 2."] },
    { type: "deep", sections: [
      { h: "A complete example", paras: ["A disk turns at 7200 rpm. One rotation takes 60 / 7200 = 8.33 ms, so the average rotational latency is 4.17 ms. The average seek is 6 ms. A track has 200 sectors of 512 bytes (102,400 bytes), so one sector passes the head in 8.33 / 200 = 0.042 ms. With a 0.2 ms controller overhead, reading one sector takes 6 + 4.17 + 0.04 + 0.2 = 10.41 ms; reading 4 KB (8 consecutive sectors) takes 6 + 4.17 + 0.33 + 0.2 = 10.70 ms.", "The streaming rate is 102,400 bytes per rotation × 120 rotations per second = 12,288,000 bytes per second. Reading 4 KB at random therefore delivers 4096 / 10.7 ms ≈ 0.38 MB/s, thirty times slower than streaming. Faster spindles cut the latency: at 15,000 rpm a rotation is 4 ms and the average latency 2 ms.", "Capacity: with 16 surfaces (8 platters), 2000 tracks per surface, 400 sectors per track and 512 bytes per sector, the disk holds 16 × 2000 × 400 × 512 = 6,553,600,000 bytes. Real disks use zoned recording, with more sectors on the longer outer tracks, so the capacity formula uses the average or is given zone by zone."] },
      { h: "RAID in detail", paras: ["RAID 0 stripes blocks over all disks, so large transfers run in parallel and capacity is the sum, but one failure loses everything. RAID 1 writes every block to two disks; reads can use either. It survives a failure and halves the capacity. RAID 10 stripes across mirrored pairs. RAID 5 keeps, in each stripe, one block of parity (the XOR of the data blocks), placed on a different disk in each stripe so that no disk is a bottleneck. If a disk fails, each lost block is the XOR of the surviving blocks of its stripe. RAID 6 stores two independent parities and survives two failures.", "Small writes cost more in RAID 5. To change one block the controller reads the old data and the old parity, computes the new parity (old parity XOR old data XOR new data), and writes the new data and new parity: 4 disk accesses for one logical write. RAID 1 needs 2 writes, RAID 6 needs 6.", "Example: 8 disks of 2 TB. RAID 0 gives 16 TB, RAID 1 and RAID 10 give 8 TB, RAID 5 gives 14 TB, RAID 6 gives 12 TB."] },
      { h: "Flash and solid-state drives", paras: ["A solid-state drive stores bits in NAND flash cells and has no moving parts, so there is no seek and no rotational delay: a random read takes tens of microseconds. But flash is written in pages (a few KB) and erased in much larger blocks, and a page can be written only after its block has been erased. Updating data in place is therefore impossible; the controller writes the new version elsewhere and later erases old blocks, which makes the actual amount written larger than what the host asked (write amplification). Each block survives only a limited number of erase cycles, so the controller also spreads the wear evenly (wear levelling).", "In short: HDD is cheap per byte and good at streaming, SSD is fast at random access and has a limited write endurance."] },
    ] },
    { type: "walkthrough", steps: ["Find the rotation time: 60000 / rpm milliseconds; the average latency is half of it.", "Find the transfer time: (bytes requested / bytes per track) × rotation time.", "Add the average seek and any controller time.", "For capacity multiply surfaces × tracks × sectors × bytes per sector.", "For RAID, pick the level's usable fraction and the number of failures it tolerates; use 4 accesses for a small RAID 5 write."], prompt: { q: "A disk turns at 10,000 rpm. What is its average rotational latency?", a: "Rotation = 6 ms; half of it is 3 ms." } },
    { type: "figure", id: "disk-tbl", for: "ex1", caption: "Reading one 512-byte sector from the example disk.", alt: "Seek 6 ms, rotational latency 4.17 ms, transfer 0.04 ms, controller 0.2 ms, total 10.41 ms.", fig: { kind: "matrix", title: "Access time", cols: ["ms"], rows: [{ label: "Average seek", cells: [6] }, { label: "Average rotational latency", cells: [4.17] }, { label: "Transfer of one sector", cells: [0.04] }, { label: "Controller", cells: [0.2] }, { label: "Total", cells: [10.41], hl: true }] } },
    { type: "figure", id: "raid-tbl", for: "ex2", caption: "RAID levels for 8 disks of 2 TB.", alt: "RAID 0 16 TB survives 0; RAID 1 and 10 8 TB survive 1; RAID 5 14 TB survives 1; RAID 6 12 TB survives 2.", fig: { kind: "matrix", title: "RAID", cols: ["usable (TB)", "failures survived", "accesses per small write"], rows: [{ label: "RAID 0", cells: [16, 0, 1] }, { label: "RAID 1 / 10", cells: [8, 1, 2] }, { label: "RAID 5", cells: [14, 1, 4], hl: true }, { label: "RAID 6", cells: [12, 2, 6] }] } },
    { type: "example", id: "ex1", level: "gate", title: "Disk access time", given: "A disk turns at 7200 rpm with an average seek of 6 ms. A track holds 200 sectors of 512 bytes. The controller adds 0.2 ms.", find: "The average time to read one sector, and to read 4 KB.",
      steps: [{ say: "Rotation = 60000 / 7200 = 8.33 ms; average latency 4.17 ms.", result: "4.17 ms" }, { say: "One sector: 8.33 / 200 = 0.04 ms. Total = 6 + 4.17 + 0.04 + 0.2.", result: "10.41 ms" }, { say: "4 KB = 8 sectors = 8/200 of a rotation = 0.33 ms. Total = 6 + 4.17 + 0.33 + 0.2.", result: "10.70 ms" }],
      answer: "10.41 ms for a sector and 10.70 ms for 4 KB.", check: "Enter the values in the disk lab." },
    { type: "example", id: "ex2", level: "gate", title: "RAID capacity", given: "Eight disks of 2 TB each.", find: "The usable capacity and fault tolerance of RAID 0, 1, 5 and 6.",
      steps: [{ say: "RAID 0 uses everything: 16 TB, no failure survived.", result: "16 TB, 0" }, { say: "RAID 1 mirrors: 8 TB, survives 1.", result: "8 TB, 1" }, { say: "RAID 5 gives up one disk of parity: 14 TB, survives 1.", result: "14 TB, 1" }, { say: "RAID 6 gives up two: 12 TB, survives 2.", result: "12 TB, 2" }],
      answer: "16, 8, 14 and 12 TB; tolerating 0, 1, 1 and 2 failures.", check: "RAID 5 and 6 cost the least capacity for their protection." },
    { type: "example", id: "ex3", level: "edge", title: "Rebuilding from parity", given: "A RAID 5 stripe holds data blocks 1011, 0110 and 1100 and a parity block. The disk with the second block fails.", find: "The parity block, and the lost block.",
      steps: [{ say: "Parity = XOR of the data: 1011 ⊕ 0110 = 1101; 1101 ⊕ 1100 = 0001.", result: "0001" }, { say: "Lost block = XOR of the survivors and the parity: 1011 ⊕ 1100 ⊕ 0001.", result: "0110" }],
      answer: "Parity 0001; the lost block is 0110.", check: "XOR is its own inverse, which is why parity works." },
    { type: "lab", lab: "mem-disk" },
    { type: "faded", title: "Your turn", given: "A disk turns at 10,000 rpm, the average seek is 4 ms, a track holds 500 sectors of 512 bytes, and the controller adds nothing.", steps: [{ say: "Rotation time and average latency?", blank: true, answer: "6 ms; 3 ms." }, { say: "Time to read one sector?", blank: true, answer: "4 + 3 + 6/500 = 7.012 ms." }, { say: "Streaming rate?", blank: true, answer: "256,000 B/track × 166.7 rev/s = about 42.7 MB/s." }] },
    { type: "trap", wrong: "The average rotational latency is one full rotation.", tempting: "The sector could be anywhere.", whyWrong: "On average the wanted sector is half a turn away.", rule: "Average rotational latency = ½ × (60 / rpm)." },
    { type: "trap", wrong: "A RAID 5 small write is one disk access.", tempting: "Only one block changes.", whyWrong: "The parity must change too: read old data and parity, write new data and parity, 4 accesses.", rule: "Small write: RAID 1 = 2, RAID 5 = 4, RAID 6 = 6." },
    { type: "trap", wrong: "RAID 0 is a redundant array.", tempting: "It is a RAID level.", whyWrong: "RAID 0 only stripes; it has no redundancy and a single failure loses the data.", rule: "RAID 0 = speed and capacity, no protection." },
    { type: "shortcut", text: "Access = seek + ½ × (60/rpm) + (x / bytes per track) × (60/rpm) + controller. Capacity = surfaces × tracks × sectors × bytes. RAID usable: 0 → N·d, 1/10 → N·d/2, 5 → (N−1)·d, 6 → (N−2)·d.", validWhen: "Average seek is given and the sectors of the request are consecutive on one track." },
    { type: "gate", text: "GATE asks for the average time to read a block from a disk, the capacity of a disk, the transfer rate, the number of cylinders or tracks needed for a file, the usable capacity and fault tolerance of RAID levels, and the difference between disks and flash. Disk-timing questions appear almost every year." },
    { type: "recall", cards: [{ q: "Average rotational latency", a: "half a rotation = 30 / rpm seconds" }, { q: "Disk access time", a: "seek + latency + transfer + controller" }, { q: "RAID 5 capacity", a: "(N − 1) × disk size" }, { q: "RAID 5 small write", a: "4 disk accesses" }, { q: "Flash write rule", a: "erase a block before rewriting a page" }] },
    { type: "check", questions: [
      { id: "dk1", kind: "NAT", marks: 1, q: "A disk turns at 7200 rpm. What is its average rotational latency in ms (two decimals)?", answer: "4.17", solution: "Half of 8.33 ms." },
      { id: "dk2", kind: "NAT", marks: 2, q: "The average seek is 6 ms, the disk turns at 7200 rpm, a track has 200 sectors of 512 bytes and the controller takes 0.2 ms. What is the average time to read one sector in ms (two decimals)?", answer: "10.41", solution: "6 + 4.17 + 0.04 + 0.2." },
      { id: "dk3", kind: "NAT", marks: 2, q: "A disk has 16 surfaces, 2000 tracks per surface, 400 sectors per track and 512 bytes per sector. What is its capacity in bytes?", answer: "6553600000", solution: "16 × 2000 × 400 × 512." },
      { id: "dk4", kind: "NAT", marks: 2, q: "Eight disks of 2 TB are set up as RAID 5. What is the usable capacity in TB?", answer: "14", solution: "(8 − 1) × 2." },
      { id: "dk5", kind: "MSQ", marks: 2, q: "Which statements are true?", options: ["RAID 6 survives two disk failures", "RAID 1 halves the capacity", "RAID 0 survives one failure", "A small write in RAID 5 takes 4 disk accesses"], answer: "A, B, D", solution: "RAID 0 has no redundancy." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Disks and RAID", href: TP }, { label: "Topic 1: chips and decoding", sub: "Memory design", href: HREF }, { label: "Topic 4: error correction", sub: "Parity and Hamming", href: HREF }] },
    { type: "links", prereq: ["Memory hierarchy", "XOR"], usedIn: ["Disk scheduling (OS)", "File systems (OS)"], cross: ["OS: disk scheduling", "DBMS: storage and indexing"] },
  ],
};

/* ------------------------------------------------------------------ 4. Error correction */
const eccT: Topic = {
  id: "cs.coa.ecc",
  title: "Error detection and correction: parity, Hamming and SECDED",
  blocks: [
    { type: "hook", text: "A cosmic ray, a weak cell or a noisy wire flips a bit in memory, and the program silently computes a wrong answer. Memory systems defend against this with a few extra bits per word. With one extra bit you can notice a single error; with a few more you can find the wrong bit and put it right, the whole idea behind the Hamming code." },
    { type: "objectives", items: ["Use even and odd parity, and say which errors it detects.", "Define the Hamming distance and say what a code of a given distance can detect and correct.", "Compute the number of check bits of a Hamming code and build and decode a codeword.", "Explain SECDED and compute its overhead for 64-bit words."] },
    { type: "intuition", paras: ["Parity: add one bit chosen so that the number of 1s in the word is even (even parity). If one bit flips, the count becomes odd and the receiver knows something is wrong. It cannot say which bit, and two flips cancel out and go unnoticed.", "The Hamming distance between two words is the number of positions in which they differ. If every pair of valid code words differs in at least d positions, then up to d − 1 errors turn a code word into something that is not a code word (detection), and up to ⌊(d − 1)/2⌋ errors leave the received word nearer to the right code word than to any other (correction).", "Hamming's trick for d = 3 is to use several parity bits, each covering a different overlapping set of positions. When a single bit flips, a different combination of parity checks fails, and the pattern of failures (the syndrome) spells out the position of the bad bit."] },
    { type: "definition", name: "Hamming code (even parity)", text: "For m data bits and r check bits, n = m + r:", items: ["r must satisfy 2ʳ ≥ m + r + 1: m = 4 → 3, 8 → 4, 16 → 5, 32 → 6, 64 → 7.", "Number the positions 1 … n. Check bits are at positions that are powers of two (1, 2, 4, 8, …); data bits fill the others in order.", "Check bit at position 2ᵏ makes even the parity of all positions whose binary number has bit k set.", "Syndrome: recompute the checks on the received word; read the failed ones as a binary number. Zero means no single error; otherwise it is the position of the wrong bit. Flip it.", "SECDED (single-error correct, double-error detect): add one overall parity bit, r + 1 in all. For 64 data bits that is 8 bits: a 72-bit word."] },
    { type: "deep", sections: [
      { h: "Hamming(7,4), step by step", paras: ["Data bits d₁ d₂ d₃ d₄ = 1 0 1 1 go to positions 3, 5, 6, 7. Check bits p₁, p₂, p₃ are at positions 1, 2, 4. Position 1 covers positions with bit 0 set: 1, 3, 5, 7. Position 2 covers 2, 3, 6, 7. Position 4 covers 4, 5, 6, 7.", "p₁ = d₁ ⊕ d₂ ⊕ d₄ (positions 3, 5, 7) = 1 ⊕ 0 ⊕ 1 = 0. p₂ = d₁ ⊕ d₃ ⊕ d₄ (positions 3, 6, 7) = 1 ⊕ 1 ⊕ 1 = 1. p₃ = d₂ ⊕ d₃ ⊕ d₄ (positions 5, 6, 7) = 0 ⊕ 1 ⊕ 1 = 0. The code word, in position order, is p₁ p₂ d₁ p₃ d₂ d₃ d₄ = 0 1 1 0 0 1 1.", "Suppose position 5 is flipped in storage: 0 1 1 0 1 1 1. Recompute: the check on positions 1, 3, 5, 7 = 0 ⊕ 1 ⊕ 1 ⊕ 1 = 1 (fails, contributes 1); on positions 2, 3, 6, 7 = 1 ⊕ 1 ⊕ 1 ⊕ 1 = 0 (passes); on positions 4, 5, 6, 7 = 0 ⊕ 1 ⊕ 1 ⊕ 1 = 1 (fails, contributes 4). The syndrome is 1 + 4 = 5: position 5 is wrong. Flip it back and read the data 1 0 1 1."] },
      { h: "Why the bound is what it is", paras: ["A single error can be in any of the n positions, or there can be no error: n + 1 situations that the r check bits must tell apart, and r bits can describe 2ʳ situations. So 2ʳ ≥ n + 1 = m + r + 1. For 4 data bits r = 3 gives 8 ≥ 8; for 64 data bits r = 7 gives 128 ≥ 72, and r = 6 would give only 64 < 72.", "SECDED: the Hamming code has distance 3, so a double error can look like a single error at another position and be 'corrected' wrongly. Adding one parity bit over the whole word (distance 4) lets the decoder see that the overall parity is right while the syndrome is not zero: that can only be a double error, which it reports but cannot fix. Server memory uses 72 bits to store 64 data bits (12.5% overhead), correcting one flipped bit per word and detecting two."] },
      { h: "Parity and the other codes", paras: ["Simple parity has distance 2: it detects every odd number of errors and corrects none. It is cheap, one bit per byte or per word, and is used where an error can be handled by retrying (a cache tag, a bus). Disks and networks use stronger codes, CRC and Reed–Solomon, which detect bursts of errors; the principle is the same: spend extra bits to make valid words far apart."] },
    ] },
    { type: "walkthrough", steps: ["Find r from 2ʳ ≥ m + r + 1.", "Number the positions 1 … m + r; put check bits at the powers of two and the data in order in the rest.", "Compute each check bit as the parity of the positions it covers (those with its bit set), excluding itself.", "To decode, recompute each check over the received word; the failed checks, as a binary number, give the syndrome.", "A non-zero syndrome is the position of the wrong bit: flip it. For SECDED, a non-zero syndrome with correct overall parity means a double error."], prompt: { q: "How many check bits does a Hamming code need for 8 data bits?", a: "4, since 2⁴ = 16 ≥ 8 + 4 + 1 = 13 but 2³ = 8 < 8 + 3 + 1 = 12." } },
    { type: "figure", id: "ham-tbl", for: "ex1", caption: "Hamming(7,4) for data 1011: which positions each check covers.", alt: "p1 covers 1, 3, 5, 7. p2 covers 2, 3, 6, 7. p3 covers 4, 5, 6, 7. The code word is 0110011.", fig: { kind: "matrix", title: "Check bits", cols: ["covers", "value"], rows: [{ label: "p1 (position 1)", cells: ["1, 3, 5, 7", 0] }, { label: "p2 (position 2)", cells: ["2, 3, 6, 7", 1] }, { label: "p3 (position 4)", cells: ["4, 5, 6, 7", 0] }, { label: "Code word 0110011", cells: ["p1 p2 d1 p3 d2 d3 d4", ""], hl: true }] } },
    { type: "figure", id: "bits-tbl", for: "ex2", caption: "Check bits against the data width.", alt: "4 data bits need 3 check bits, 8 need 4, 16 need 5, 32 need 6, 64 need 7, and SECDED adds one.", fig: { kind: "matrix", title: "Overhead", cols: ["Hamming check bits", "SECDED bits", "overhead (SECDED)"], rows: [{ label: "4 data bits", cells: [3, 4, "100%"] }, { label: "8 data bits", cells: [4, 5, "62.5%"] }, { label: "16 data bits", cells: [5, 6, "37.5%"] }, { label: "32 data bits", cells: [6, 7, "21.9%"] }, { label: "64 data bits", cells: [7, 8, "12.5%"], hl: true }] } },
    { type: "example", id: "ex1", level: "gate", title: "Encode and correct", given: "Data bits 1011 are stored with Hamming(7,4) (even parity). Position 5 is flipped.", find: "The code word, the syndrome and the corrected data.",
      steps: [{ say: "p₁ = 1⊕0⊕1 = 0; p₂ = 1⊕1⊕1 = 1; p₃ = 0⊕1⊕1 = 0. The code word is 0 1 1 0 0 1 1.", result: "0110011" }, { say: "After the flip the word is 0110111. The checks over {1,3,5,7} and {4,5,6,7} fail, {2,3,6,7} passes: syndrome = 1 + 4.", result: "syndrome 5" }, { say: "Flip position 5 back: 0110011, data 1011.", result: "1011" }],
      answer: "Code word 0110011; syndrome 5; corrected data 1011.", check: "Flip any bit of the stored word in the Hamming lab." },
    { type: "example", id: "ex2", level: "gate", title: "Check bits and overhead", given: "A memory word has 64 data bits.", find: "The check bits for single-error correction, and for SECDED.",
      steps: [{ say: "2⁶ = 64 < 64 + 6 + 1 = 71, but 2⁷ = 128 ≥ 72.", result: "r = 7" }, { say: "SECDED adds one overall parity bit.", result: "8 bits" }],
      answer: "7 check bits; 8 for SECDED, a 72-bit word (12.5% overhead).", check: "The overhead falls as words get wider." },
    { type: "example", id: "ex3", level: "edge", title: "What a code can do", given: "A code has minimum Hamming distance 4.", find: "How many errors it detects and how many it corrects.",
      steps: [{ say: "Detects d − 1 errors.", result: "3" }, { say: "Corrects ⌊(d − 1)/2⌋ errors.", result: "1" }],
      answer: "Detects 3 errors and corrects 1.", check: "That is exactly SECDED's strength with distance 4: correct 1, detect 2." },
    { type: "lab", lab: "mem-hamming" },
    { type: "faded", title: "Your turn", given: "Encode the data 0110 with Hamming(7,4), even parity.", steps: [{ say: "Place the data in positions 3, 5, 6, 7.", blank: true, answer: "d₁d₂d₃d₄ = 0,1,1,0 at positions 3,5,6,7." }, { say: "p₁ (3,5,7), p₂ (3,6,7), p₃ (5,6,7)?", blank: true, answer: "p₁ = 0⊕1⊕0 = 1; p₂ = 0⊕1⊕0 = 1; p₃ = 1⊕1⊕0 = 0." }, { say: "The code word?", blank: true, answer: "1 1 0 0 1 1 0." }] },
    { type: "trap", wrong: "Parity can correct a single error.", tempting: "It notices the error.", whyWrong: "It only says that an odd number of bits flipped; it cannot say which one.", rule: "Parity detects odd errors and corrects none." },
    { type: "trap", wrong: "r check bits need only 2ʳ ≥ m.", tempting: "They must label the data bits.", whyWrong: "They must label every position, including the check bits themselves, and also 'no error': 2ʳ ≥ m + r + 1.", rule: "2ʳ ≥ m + r + 1." },
    { type: "trap", wrong: "A Hamming code detects two errors.", tempting: "It corrects one.", whyWrong: "With distance 3 two errors look like one at another position and get 'corrected' wrongly. Detecting two needs the extra overall parity bit (SECDED).", rule: "Hamming: correct 1. SECDED: correct 1, detect 2." },
    { type: "shortcut", text: "2ʳ ≥ m + r + 1. Check bits at positions 1, 2, 4, 8… Syndrome = sum of the failing checks' positions = the wrong position. SECDED = r + 1. Distance d: detects d − 1, corrects ⌊(d − 1)/2⌋.", validWhen: "Even-parity Hamming code with at most one error per word (two for SECDED detection)." },
    { type: "gate", text: "GATE asks for the number of check bits for a given data width, the code word and the position of an error, what a code of a given minimum distance detects and corrects, and the overhead of SECDED. Error-correction questions come up every few years." },
    { type: "recall", cards: [{ q: "Hamming bound", a: "2ʳ ≥ m + r + 1" }, { q: "Check bit positions", a: "1, 2, 4, 8, … (powers of two)" }, { q: "Syndrome", a: "position of the single wrong bit" }, { q: "SECDED", a: "Hamming + overall parity: correct 1, detect 2" }, { q: "Distance d", a: "detects d−1, corrects ⌊(d−1)/2⌋" }] },
    { type: "check", questions: [
      { id: "ec1", kind: "NAT", marks: 1, q: "How many check bits does a single-error-correcting Hamming code need for 8 data bits?", answer: "4", solution: "2⁴ = 16 ≥ 8 + 4 + 1." },
      { id: "ec2", kind: "NAT", marks: 2, q: "How many bits does a SECDED code need in all for 64 data bits?", answer: "72", solution: "64 + 7 + 1." },
      { id: "ec3", kind: "NAT", marks: 2, q: "Hamming(7,4) with even parity is used with the check bits at positions 1, 2 and 4. The stored word 0110111 is read back (the data was 1011). What is the position of the wrong bit?", answer: "5", solution: "Checks over {1,3,5,7} and {4,5,6,7} fail: 1 + 4." },
      { id: "ec4", kind: "NAT", marks: 1, q: "A code has minimum Hamming distance 5. How many errors can it correct?", answer: "2", solution: "⌊(5 − 1)/2⌋." },
      { id: "ec5", kind: "MSQ", marks: 2, q: "Which statements are true?", options: ["A single parity bit detects any odd number of bit errors", "A Hamming code (distance 3) can correct a single error", "A Hamming code can always detect two errors without correcting wrongly", "SECDED corrects one error and detects two"], answer: "A, B, D", solution: "With two errors a plain Hamming code may 'correct' the wrong bit." },
    ] },
    { type: "practice", links: [{ label: "Real GATE questions on Computer Organisation", sub: "Error correction", href: TP }, { label: "Topic 3: disks and RAID", sub: "Parity in RAID", href: HREF }, { label: "Topic 1: chips and decoding", sub: "Memory design", href: HREF }] },
    { type: "links", prereq: ["XOR and parity", "Memory chips"], usedIn: ["ECC memory", "RAID parity"], cross: ["CN: CRC and error detection", "DL: parity generators"] },
  ],
};

